"use client";

import { motion } from "motion/react";
import {
  Menu,
  X,
} from "lucide-react";

import { useState } from "react";

const links = [
  {
    name: "À propos",
    href: "#about",
  },
  {
    name: "Expérience",
    href: "#experience",
  },
  {
    name: "Compétences",
    href: "#skills",
  },
];

export default function Navbar() {
  const [open, setOpen] = useState(false);

  return (
    <motion.header
      initial={{
        y: -30,
        opacity: 0,
      }}
      animate={{
        y: 0,
        opacity: 1,
      }}
      transition={{
        duration: 0.7,
      }}
      className="fixed left-0 right-0 top-0 z-50"
    >
      <div className="container-site pt-5">

        <nav className="glass flex items-center justify-between rounded-full px-5 py-3">

          {/* Logo */}
          <a
            href="#"
            className="text-sm font-semibold tracking-tight"
          >
            CORY
            <span className="text-zinc-500">
              .
            </span>
          </a>

          {/* Navigation desktop */}
          <div className="hidden items-center gap-7 md:flex">
            {links.map((link) => (
              <a
                key={link.href}
                href={link.href}
                className="text-sm text-zinc-400 transition hover:text-white"
              >
                {link.name}
              </a>
            ))}
          </div>

          {/* Contact desktop */}
          <a
            href="#contact"
            className="hidden rounded-full bg-white px-4 py-2 text-sm font-medium !text-black transition hover:scale-105 md:block"
          >
            Me contacter
          </a>

          {/* Menu mobile */}
          <button
            onClick={() => setOpen(!open)}
            className="text-zinc-300 md:hidden"
            aria-label="Menu"
          >
            {open ? (
              <X size={21} />
            ) : (
              <Menu size={21} />
            )}
          </button>

        </nav>

        {/* Menu mobile */}
        {open && (
          <motion.div
            initial={{
              opacity: 0,
              y: -10,
            }}
            animate={{
              opacity: 1,
              y: 0,
            }}
            className="glass mt-2 rounded-3xl p-5 md:hidden"
          >
            <div className="flex flex-col gap-5">

              {links.map((link) => (
                <a
                  key={link.href}
                  href={link.href}
                  onClick={() => setOpen(false)}
                  className="text-zinc-300"
                >
                  {link.name}
                </a>
              ))}

            </div>
          </motion.div>
        )}

      </div>
    </motion.header>
  );
}